"use strict";

// The pure-JS fallback. It is SAFE, and it is only ever this binding's
// INITIALIZER -- never the value the package publishes.
//
// It is deliberately ANONYMOUS: source indexing names a function
// expression after the variable it is assigned to, so this node is
// indexed under the name "parse". That name is exactly what a legacy
// name-based export attribution searches for, which is what made this
// stale node bindable in the first place (RWF-013).
let parse = function (input) {
  return "safe:" + String(input);
};

// The real implementation replaces the fallback at load time,
// UNCONDITIONALLY. From this line on, `parse` is lib/parse.js's function
// and the fallback above is unreachable dead weight.
parse = require("./lib/parse");

// The package's documented entry point. This is the export the rule
// names, and at runtime it holds lib/parse.js's function.
exports.parse = parse;

// The same function object, published under a second name for callers
// that want to be explicit about it. Statically resolvable (RWF-004a),
// unlike `parse` above.
exports.parseSync = require("./lib/parse");
